import fitz
d=fitz.open('eprint/sidecarRF.pdf'.replace('sidecarRF','sidecar_limit_plot_2021_final_prl_oct11'))
p=d[0]
dr=p.get_drawings()[77]
pts=[]
for it in dr['items']:
    if it[0]=='l':
        pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
    elif it[0]=='c':
        pts.append((it[1].x,it[1].y)); pts.append((it[4].x,it[4].y))
    elif it[0]=='re':
        print('re',it[1])
# dedupe consecutive
out=[pts[0]]
for q in pts[1:]:
    if q!=out[-1]: out.append(q)
print(len(out))
for q in out: print(round(q[0],2), round(q[1],2))
