python3 << 'EOF'
import fitz
d=fitz.open('eprint/sidecar_limit_plot_2021_final_prl_oct11.pdf')
p=d[0]
pix=p.get_pixmap(dpi=100)
pix.save('limitfig.png')
dr=p.get_drawings()[1]
pts=[]
for it in dr['items']:
    if it[0]=='l':
        for q in (it[1],it[2]): pts.append((q.x,q.y))
    elif it[0]=='c':
        pts.append((it[1].x,it[1].y)); pts.append((it[4].x,it[4].y))
out=[pts[0]]
for q in pts[1:]:
    if q!=out[-1]: out.append(q)
print(len(out))
for q in out:
    print(round(q[0],2), round(q[1],2))
EOF
